#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int largestAltitude(vector<int>& gain) {
        int curr = 0;
        int mx = 0;
        for (int g : gain) {
            curr += g;
            mx = max(mx, curr);
        }
        return mx;
    }
};

class Solution {
    public int largestAltitude(int[] gain) {
        int curr = 0;
        int mx = 0;
        for (int g : gain) {
            curr += g;
            if (curr > mx) mx = curr;
        }
        return mx;
    }
}

/**
 * @param {number[]} gain
 * @return {number}
 */
var largestAltitude = function(gain) {
    let curr = 0;
    let mx = 0;
    for (const g of gain) {
        curr += g;
        if (curr > mx) mx = curr;
    }
    return mx;
};
